"""Conversation reconstruction shared by the collector and packet builder."""

import re
from datetime import datetime

IDLE_GAP_SECONDS = 30 * 60

# Prefixes of user messages that Claude Code inserts and a person did not type.
SYNTHETIC_USER_PREFIXES = (
    "<local-command-caveat>",
    "<local-command-",
    "<teammate-message",
    "<task-notification",
    "<system-reminder>",
    "Another Claude session sent a message:",
    "Base directory for this skill:",
    "Caveat: The messages below were generated by the user while running local commands.",
    "This session is being continued from a previous conversation",
)


def timestamp_to_epoch(timestamp):
    if not timestamp:
        return None
    value = str(timestamp)
    if value.endswith("Z"):
        value = value[:-1]
    if "." in value:
        value = value.split(".", 1)[0]
    for suffix in ("+00:00", "-00:00"):
        if value.endswith(suffix):
            value = value[:-len(suffix)]
    try:
        return int((datetime.strptime(value, "%Y-%m-%dT%H:%M:%S") - datetime(1970, 1, 1)).total_seconds())
    except Exception:
        return None


def duration_metrics(entries):
    timestamps = []
    for entry in entries:
        # Only conversation entries: system entries such as away_summary are
        # written minutes after the turn ends.
        if not is_conversation_message(entry):
            continue
        epoch = timestamp_to_epoch(entry.get("timestamp"))
        if epoch is not None:
            timestamps.append(epoch)
    if not timestamps:
        return {"wall_duration_minutes": 0, "active_duration_minutes": 0, "large_idle_gap_count": 0}

    timestamps.sort()
    wall = max(0, int(round((timestamps[-1] - timestamps[0]) / 60.0)))
    active_seconds = 0
    large_gaps = 0
    for idx in range(1, len(timestamps)):
        gap = timestamps[idx] - timestamps[idx - 1]
        if gap > IDLE_GAP_SECONDS:
            large_gaps += 1
        else:
            active_seconds += max(0, gap)
    return {
        "wall_duration_minutes": wall,
        "active_duration_minutes": int(round(active_seconds / 60.0)),
        "large_idle_gap_count": large_gaps,
    }


def is_conversation_message(msg):
    return msg.get("type") in ("user", "assistant")


def is_synthetic_user_text(text):
    trimmed = text.strip()
    return (
        trimmed.startswith(SYNTHETIC_USER_PREFIXES)
        or re.search(r"<command-name>/(clear|exit)</command-name>", trimmed) is not None
    )


def synthetic_user_label(msg, text):
    """Timeline label for a user entry that a person did not type, or "" if typed.

    Since 2.1.304 or earlier Claude Code marks user entries with origin.kind
    ("human", "task-notification", "peer", ...). Older entries have no origin;
    for them isMeta and the text prefixes decide. A subagent's task prompt has
    no origin and stays [User].
    """
    origin = msg.get("origin")
    kind = origin.get("kind") if isinstance(origin, dict) else None
    trimmed = text.strip()
    if kind == "task-notification" or trimmed.startswith("<task-notification"):
        return "[Task notification]"
    if kind == "peer" or trimmed.startswith("Another Claude session sent a message:"):
        return "[Agent message]"
    if kind and kind != "human":
        return "[System: %s]" % kind
    if msg.get("isMeta") is True or is_synthetic_user_text(text):
        return "[System]"
    return ""


def user_texts(msg):
    content = msg.get("message", {}).get("content")
    if isinstance(content, str):
        return [content] if content.strip() else []
    texts = []
    if isinstance(content, list):
        for block in content:
            if isinstance(block, dict) and block.get("type") == "text":
                text = str(block.get("text", ""))
                if text.strip():
                    texts.append(text)
    return texts


def has_human_user_text(msg):
    if msg.get("type") != "user":
        return False
    return any(not synthetic_user_label(msg, text) for text in user_texts(msg))


def build_chain(leaf, by_id):
    chain = []
    seen = set()
    current = leaf
    while current is not None:
        uuid = current.get("uuid")
        if not uuid or uuid in seen:
            break
        seen.add(uuid)
        chain.append(current)
        parent = parent_uuid(current)
        current = by_id.get(parent) if parent else None
    chain.reverse()
    return chain


def parent_uuid(entry):
    """The entry's parent. A compact boundary has parentUuid null and links to
    the conversation before the compaction only through logicalParentUuid."""
    return entry.get("parentUuid") or entry.get("logicalParentUuid")


def tool_ids_in(msg, block_type, key):
    content = msg.get("message", {}).get("content")
    ids = set()
    if isinstance(content, list):
        for block in content:
            if isinstance(block, dict) and block.get("type") == block_type and isinstance(block.get(key), str):
                ids.add(block.get(key))
    return ids


def add_parallel_branches(chain, entries):
    """Put back the side branches that parallel tool calls leave.

    One response with several tool_use blocks is written as several assistant
    entries sharing message.id. Each tool_result hangs off its own tool_use
    entry, and the conversation continues from only one of them, so a single
    parent chain misses the other calls. Add the assistant entries of the same
    responses and the results of their tool calls, in file order.
    """
    if not chain:
        return chain
    chain_uuids = set(msg.get("uuid") for msg in chain if msg.get("uuid"))
    message_ids = set()
    tool_ids = set()
    for msg in chain:
        if msg.get("type") == "assistant":
            message_id = msg.get("message", {}).get("id")
            if message_id:
                message_ids.add(message_id)
            tool_ids |= tool_ids_in(msg, "tool_use", "id")
    extra = []
    for entry in entries:
        uuid = entry.get("uuid")
        if not uuid or uuid in chain_uuids or entry.get("type") != "assistant":
            continue
        if entry.get("message", {}).get("id") in message_ids:
            extra.append(entry)
            chain_uuids.add(uuid)
            tool_ids |= tool_ids_in(entry, "tool_use", "id")
    for entry in entries:
        uuid = entry.get("uuid")
        if not uuid or uuid in chain_uuids or entry.get("type") != "user":
            continue
        if tool_ids_in(entry, "tool_result", "tool_use_id") & tool_ids:
            extra.append(entry)
            chain_uuids.add(uuid)
    if not extra:
        return chain
    order = {}
    for idx, entry in enumerate(entries):
        uuid = entry.get("uuid")
        if uuid:
            order[uuid] = idx
    merged = chain + extra
    merged.sort(key=lambda msg: order.get(msg.get("uuid"), len(entries)))
    return merged


def duration_minutes(chain):
    if not chain:
        return 0
    start = timestamp_to_epoch(chain[0].get("timestamp"))
    end = timestamp_to_epoch(chain[-1].get("timestamp"))
    if start is None or end is None:
        return 0
    return int(round((end - start) / 60.0))


def count_human_users(chain):
    return sum(1 for msg in chain if has_human_user_text(msg))


def select_conversation(entries):
    by_id = {}
    parent_ids = set()
    children_by_parent = {}
    for entry in entries:
        uuid = entry.get("uuid")
        if not uuid:
            continue
        by_id[uuid] = entry
        parent = parent_uuid(entry)
        if parent:
            parent_ids.add(parent)
            children_by_parent.setdefault(parent, []).append(entry)

    if not by_id:
        return entries

    terminal = [msg for uuid, msg in by_id.items() if uuid not in parent_ids]
    leaf_by_uuid = {}
    for term in terminal:
        seen = set()
        current = term
        while current is not None:
            uuid = current.get("uuid")
            if not uuid or uuid in seen:
                break
            seen.add(uuid)
            if is_conversation_message(current):
                leaf_by_uuid[uuid] = current
                break
            parent = parent_uuid(current)
            current = by_id.get(parent) if parent else None

    if not leaf_by_uuid and by_id:
        for msg in reversed(list(by_id.values())):
            if is_conversation_message(msg):
                leaf_by_uuid[msg.get("uuid")] = msg
                break

    # Pick the branch whose last message was written last, as Claude Code does
    # when it resumes. A rewound or edited message leaves the older attempt as
    # a side branch, and parallel tool calls leave dead-end siblings; both end
    # earlier. Human message count and duration only break ties.
    best_chain = []
    best_key = None
    for leaf in leaf_by_uuid.values():
        chain = build_chain(leaf, by_id)
        key = (
            timestamp_to_epoch(leaf.get("timestamp")) or 0,
            count_human_users(chain),
            duration_minutes(chain),
        )
        if best_key is None or key > best_key:
            best_chain = chain
            best_key = key

    if best_chain:
        leaf = best_chain[-1]
        leaf_uuid = leaf.get("uuid")
        if leaf_uuid in children_by_parent:
            trailing = sorted(children_by_parent[leaf_uuid], key=lambda m: str(m.get("timestamp", "")))
            for msg in trailing:
                uuid = msg.get("uuid")
                if uuid not in leaf_by_uuid:
                    best_chain.append(msg)

    return add_parallel_branches(best_chain, list(by_id.values())) or entries
